import { useState } from "react";

export function SelectableList({
  heading = "{{heading}}",
  accent = "{{accent}}",
  style = "{{style}}",
  secondChecked = {{secondChecked}},
  showCount = {{showCount}},
}) {
  const [checked, setChecked] = useState({ a: false, b: secondChecked, c: false });
  const count = Object.values(checked).filter(Boolean).length;
  const rowStyle = {
    display: "flex", alignItems: "center", gap: 10, padding: "9px 8px",
    background: style === "card" ? "#fff" : "transparent",
    borderRadius: style === "card" ? 8 : 0,
    marginBottom: style === "card" ? 6 : 0,
    boxShadow: style === "card" ? "0 1px 4px rgba(36,20,48,.08)" : "none",
    borderBottom: style === "divided" ? "1px solid #24143020" : "none",
  };
  const people = [["a", "Alicia Ferreira"], ["b", "Ben Sato"], ["c", "Charu Deshpande"]];
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 300, width: 300, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 6px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      {showCount && <p role="status" style={{ margin: "0 0 10px", fontSize: 12, color: "#241430a0" }}>{count} selected</p>}
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {people.map(([id, name]) => (
          <li key={id} style={rowStyle}>
            <input type="checkbox" id={`rsel-${id}`} checked={checked[id]} onChange={() => setChecked((c) => ({ ...c, [id]: !c[id] }))} style={{ width: 17, height: 17, accentColor: accent, cursor: "pointer" }} />
            <label htmlFor={`rsel-${id}`} style={{ cursor: "pointer" }}>{name}</label>
          </li>
        ))}
      </ul>
    </div>
  );
}
